  def ai_debug_ui_enabled?
    Rails.env.development? || Rails.env.test?
  end

  def ui_icon(name, class_name: "ui-icon")
    paths = UI_ICON_PATHS.fetch(name.to_s, UI_ICON_PATHS.fetch("sparkles"))
    raw(%(<svg class="#{ERB::Util.html_escape(class_name)}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">#{paths}</svg>))
  end
